<?php declare(strict_types=1);
$invoicePage=(new \Kulturhus\Verein\OutgoingInvoiceCatalogue($db,(string)$_SESSION['actor']))->page($_GET);$c=$invoicePage['controls'];$route=['view'=>'finance','tab'=>'outgoing']+array_diff_key($c,['invoices_page'=>true]);
?>
<div data-invoice-catalogue class="invoice-catalogue">
<form method="get" class="invoice-search"><?= hidden('view','finance').hidden('tab','outgoing') ?><label>Nummer, Empfänger oder Beschreibung<input class="form-control" name="invoices_q" maxlength="150" value="<?= e($c['invoices_q']) ?>"></label><label>Stand<select class="form-control" name="inv_status"><option value="">Alle</option><?php foreach($labels as$key=>$label): ?><option value="<?= $key ?>"<?= $c['inv_status']===$key?' selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label><label>Art<select class="form-control" name="inv_kind"><option value="">Alle</option><?php foreach($invoiceKinds as$key=>$label): ?><option value="<?= $key ?>"<?= $c['inv_kind']===$key?' selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label><button class="btn btn-solid theme-primary">Suchen</button></form>
<p><?= $invoicePage['total'] ?> Rechnungsdokumente · Seite <?= $invoicePage['page'] ?> von <?= $invoicePage['pages'] ?></p>
<div class="invoice-cards"><?php foreach($invoicePage['rows']as$row): ?><article class="card invoice-summary" data-invoice-summary><h3><?= e($row['number']?:'Noch ohne Nummer') ?></h3><p><strong><?= e($row['buyer_name']) ?></strong></p><p><?= e($row['description']) ?></p><p><?= e($invoiceKinds[$row['kind']].' · '.$labels[$row['state']]) ?></p><p><?= e(dateDe($row['document_date'])) ?> · <?= euro((int)$row['total_cents']) ?> brutto</p><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['invoices_page'=>$invoicePage['page'],'invoice'=>$row['id']])) ?>">Dokument öffnen</a></article><?php endforeach ?></div>
<?php if(!$invoicePage['rows']): ?><p>Keine passenden Rechnungsdokumente.</p><?php endif ?>
<?php if($invoicePage['pages']>1): ?><nav class="invoice-pages" aria-label="Rechnungsseiten"><?php if($invoicePage['page']>1): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['invoices_page'=>$invoicePage['page']-1])) ?>">Vorherige Seite</a><?php endif ?><?php if($invoicePage['page']<$invoicePage['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['invoices_page'=>$invoicePage['page']+1])) ?>">Nächste Seite</a><?php endif ?></nav><form method="get" class="invoice-pages"><?php foreach($route as$key=>$value)echo hidden($key,$value); ?><label>Rechnungsseite<input class="form-control" type="number" name="invoices_page" min="1" max="<?= $invoicePage['pages'] ?>" value="<?= $invoicePage['page'] ?>" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?>
</div>
